let dashboard, classeDetail, pointagePage, profilInstitution;

class ProfilInstitutionPage {
    constructor() { this.institutions = []; this.options = []; this.institutionActive = null; }
    async render() { const m = document.getElementById('main-content'); m.innerHTML = `<div style="text-align:center;padding:3rem"><div class="spinner"></div><p style="color:var(--text-muted);margin-top:0.75rem">Chargement...</p></div>`; try { const ir = await apiGet('/classes/institutions'); this.institutions = ir.data || []; const optRes = await apiGet('/classes/options/secondaire'); this.options = optRes.data || []; if (!this.institutionActive && this.institutions.length) this.institutionActive = this.institutions[0]; await this.afficher(m); } catch(e) { console.error('Erreur profil institution:', e); m.innerHTML = `<div style="text-align:center;padding:3rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--text-muted)"></i><p>${e.message}</p></div>`; } }
    getAnneeScolaire() { const now = new Date(); const mois = now.getMonth() + 1; const annee = now.getFullYear(); return mois >= 9 ? `${annee}-${annee + 1}` : `${annee - 1}-${annee}`; }
    async afficher(m) { if (!this.institutions.length) { m.innerHTML = `<div style="text-align:center;padding:4rem"><i class="fas fa-school" style="font-size:4rem;color:var(--text-muted);display:block;margin-bottom:1rem"></i><h3 style="font-weight:700;margin-bottom:0.5rem">Aucune institution</h3><p style="color:var(--text-secondary);margin-bottom:1.5rem">Créez votre première institution.</p><button class="btn btn-primary" id="btn-creer-inst-profil"><i class="fas fa-plus"></i> Créer une institution</button></div>`; m.querySelector('#btn-creer-inst-profil').onclick = () => this.ouvrirModalCreerInstitution(); return; } const inst = this.institutionActive; if (!inst) { this.institutionActive = this.institutions[0]; return this.afficher(m); } const labels = { maternelle: 'Maternelle', primaire: 'Primaire', secondaire: 'Secondaire' }, icons = { maternelle: 'child', primaire: 'child-reaching', secondaire: 'user-graduate' }, regimeLabels = { ANGLAIS: 'Anglais (Lun-Ven)', FRANCAIS: 'Français (Lun-Sam)' }; m.innerHTML = `<div style="max-width:900px;margin:0 auto;margin-top:7rem;"><div style="display:flex;align-items:center;gap:0.5rem;margin-bottom:1rem"><button class="btn btn-ghost" id="btn-retour-inst"><i class="fas fa-arrow-left"></i> Retour</button><button class="btn btn-sm btn-outline" id="btn-nettoyer-inst" style="margin-left:auto"><i class="fas fa-broom"></i> Nettoyer</button></div><div class="niveau-switcher" style="margin-bottom:1.5rem">${this.institutions.map(i => `<button class="btn btn-sm ${i.id===inst.id?'btn-primary':'btn-ghost'} switch-inst-btn" data-id="${i.id}"><i class="fas fa-${icons[i.niveau]}"></i> ${labels[i.niveau]}</button>`).join('')}</div><div class="profil-header-card"><img src="${inst.logo||'/assets/logo-ecole.png'}" alt="Logo" style="width:70px;height:70px;border-radius:16px;object-fit:cover"><div style="flex:1"><h2>${inst.nom}</h2><p style="color:var(--text-secondary)">Année scolaire ${this.getAnneeScolaire()} · <span class="badge badge-info"><i class="fas fa-calendar-week"></i> ${regimeLabels[inst.regime] || 'Anglais (Lun-Ven)'}</span></p></div><button class="btn btn-sm btn-warning" id="btn-modifier-inst"><i class="fas fa-edit"></i> Modifier</button></div><div class="profil-grid-top" style="margin-top:1rem"><div class="profil-section"><h3><i class="fas fa-info-circle"></i> Informations</h3><div class="info-liste"><div class="info-item"><span class="info-label">Adresse</span><span class="info-value">${inst.adresse||'Non renseignée'}</span></div><div class="info-item"><span class="info-label">Téléphone</span><span class="info-value">${inst.telephone||'Non renseigné'}</span></div><div class="info-item"><span class="info-label">Email</span><span class="info-value">${inst.email||'Non renseigné'}</span></div><div class="info-item"><span class="info-label">Régime</span><span class="info-value"><span class="badge badge-info"><i class="fas fa-calendar-week"></i> ${regimeLabels[inst.regime] || 'Anglais (Lun-Ven)'}</span></span></div></div></div><div class="profil-section"><h3><i class="fas fa-layer-group"></i> Niveaux</h3><div style="display:flex;flex-direction:column;gap:0.5rem">${this.institutions.map(i => `<div class="ui-card"><div style="padding:0.7rem 1rem;display:flex;align-items:center;justify-content:space-between"><span><i class="fas fa-${icons[i.niveau]}"></i> ${labels[i.niveau]}</span><button class="btn btn-sm btn-danger suppr-niveau-btn" data-id="${i.id}" data-nom="${labels[i.niveau]}"><i class="fas fa-trash"></i></button></div></div>`).join('')}</div>${this.institutions.length < 3 ? `<button class="btn btn-sm btn-primary" id="btn-ajout-niveau" style="margin-top:0.75rem;width:100%"><i class="fas fa-plus"></i> Ajouter un niveau</button>` : ''}</div></div>${inst.niveau === 'secondaire' ? `<div class="profil-section" style="margin-top:1rem;grid-column:1/-1"><h3><i class="fas fa-cogs"></i> Options (1ère - 4ème)</h3><div style="display:flex;flex-direction:column;gap:0.5rem;margin-top:1rem">${this.options.length ? this.options.map(o => `<div class="ui-card"><div style="padding:0.7rem 1rem;display:flex;align-items:center;justify-content:space-between"><span><strong>${o.code}</strong> - ${o.nom}</span><div style="display:flex;gap:0.3rem"><button class="btn btn-sm btn-warning modif-opt-btn" data-id="${o.id}" data-code="${o.code}" data-nom="${o.nom.replace(/"/g,'&quot;')}"><i class="fas fa-edit"></i></button><button class="btn btn-sm btn-danger suppr-opt-btn" data-id="${o.id}" data-nom="${o.nom.replace(/"/g,'&quot;')}"><i class="fas fa-trash"></i></button></div></div></div>`).join('') : '<p style="color:var(--text-muted);text-align:center;padding:1rem">Aucune option</p>'}</div><button class="btn btn-sm btn-primary" id="btn-ajout-opt" style="margin-top:0.75rem;width:100%"><i class="fas fa-plus"></i> Ajouter une option</button></div>` : ''}</div>`; this.bindEvents(); }
    bindEvents() { document.getElementById('btn-retour-inst')?.addEventListener('click', () => router.navigate('dashboard')); document.getElementById('btn-modifier-inst')?.addEventListener('click', () => this.ouvrirModalModifierInstitution(this.institutionActive?.id)); document.getElementById('btn-nettoyer-inst')?.addEventListener('click', () => this.nettoyerIDs()); document.getElementById('btn-ajout-niveau')?.addEventListener('click', () => this.ouvrirModalAjouterNiveau()); document.getElementById('btn-ajout-opt')?.addEventListener('click', () => this.ouvrirModalAjouterOption()); document.querySelectorAll('.switch-inst-btn').forEach(b => b.addEventListener('click', () => this.switchInstitution(parseInt(b.dataset.id)))); document.querySelectorAll('.suppr-niveau-btn').forEach(b => b.addEventListener('click', (e) => { e.stopPropagation(); this.confirmerSuppressionNiveau(parseInt(b.dataset.id), b.dataset.nom); })); document.querySelectorAll('.modif-opt-btn').forEach(b => b.addEventListener('click', (e) => { e.stopPropagation(); this.ouvrirModalModifierOption(parseInt(b.dataset.id), b.dataset.code, b.dataset.nom); })); document.querySelectorAll('.suppr-opt-btn').forEach(b => b.addEventListener('click', (e) => { e.stopPropagation(); this.confirmerSuppressionOption(parseInt(b.dataset.id), b.dataset.nom); })); }
    async switchInstitution(id) { this.institutionActive = this.institutions.find(i => i.id === id); await this.afficher(document.getElementById('main-content')); }
    ouvrirModalCreerInstitution() { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-creer-inst-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:450px" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-school"></i> Créer une institution</h3><button class="modal-close" id="close-creer-inst-profil"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Nom <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-school input-icon"></i><input type="text" class="form-input" id="creer-inst-nom-profil" placeholder="Complexe Scolaire Avenir" required></div></div><div class="input-group"><label class="input-label">Niveau <span class="required">*</span></label><div class="input-wrapper" style="cursor:pointer" id="btn-choisir-niveau-profil"><i class="fas fa-layer-group input-icon"></i><input type="text" class="form-input" id="creer-inst-niveau-nom-profil" readonly placeholder="Cliquer pour choisir..." required><input type="hidden" id="creer-inst-niveau-profil" value=""><i class="fas fa-chevron-down" style="position:absolute;right:0.8rem;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;font-size:0.8rem"></i></div></div></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-creer-inst-profil">Annuler</button><button class="btn btn-primary" id="btn-save-creer-inst-profil"><i class="fas fa-save"></i> Créer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-creer-inst-profil').onclick = () => overlay.remove(); overlay.querySelector('#cancel-creer-inst-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-choisir-niveau-profil').onclick = () => this.ouvrirModalNiveau(); overlay.querySelector('#btn-save-creer-inst-profil').onclick = () => this.creerInstitution(); }
    async ouvrirModalNiveau(){const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-niveau-profil';overlay.style.zIndex='1200';overlay.onclick=e=>{if(e.target===overlay)overlay.remove();};overlay.innerHTML=`<div class="modal" style="max-width:420px;max-height:80vh;display:flex;flex-direction:column" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-layer-group"></i> Choisir le niveau</h3><button class="modal-close" id="close-niveau-profil"><i class="fas fa-times"></i></button></div><div class="modal-body" style="flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:0.5rem;padding-bottom:0.5rem"><div class="ui-card card-hoverable" id="niv-maternelle-profil"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-child" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Maternelle</span></div></div><div class="ui-card card-hoverable" id="niv-primaire-profil"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-child-reaching" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Primaire</span></div></div><div class="ui-card card-hoverable" id="niv-secondaire-profil"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-user-graduate" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Secondaire</span></div></div></div></div>`;document.body.appendChild(overlay);overlay.querySelector('#close-niveau-profil').onclick=()=>overlay.remove();overlay.querySelector('#niv-maternelle-profil').onclick=()=>{document.getElementById('creer-inst-niveau-nom-profil').value='Maternelle';document.getElementById('creer-inst-niveau-profil').value='maternelle';overlay.remove();};overlay.querySelector('#niv-primaire-profil').onclick=()=>{document.getElementById('creer-inst-niveau-nom-profil').value='Primaire';document.getElementById('creer-inst-niveau-profil').value='primaire';overlay.remove();};overlay.querySelector('#niv-secondaire-profil').onclick=()=>{document.getElementById('creer-inst-niveau-nom-profil').value='Secondaire';document.getElementById('creer-inst-niveau-profil').value='secondaire';overlay.remove();};}
    async creerInstitution() { const nom = document.getElementById('creer-inst-nom-profil')?.value?.trim(), niveau = document.getElementById('creer-inst-niveau-profil')?.value; if (!nom || !niveau) { this.ouvrirAlert('Champs requis', 'Veuillez remplir tous les champs.', 'warning'); return; } try { const r = await apiPost('/classes/institution', { nom, niveau }); if (r.success) { document.getElementById('modal-creer-inst-profil')?.remove(); const ir = await apiGet('/classes/institutions'); this.institutions = ir.data || []; this.institutionActive = this.institutions[0] || null; await this.afficher(document.getElementById('main-content')); } else this.ouvrirAlert('Erreur', r.message || 'Échec', 'error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirModalModifierInstitution(id) { const inst = this.institutions.find(i => i.id === id); if (!inst) return; const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-modif-inst-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; const regimeActuel = inst.regime === 'FRANCAIS' ? 'Français (Lun-Sam)' : 'Anglais (Lun-Ven)'; overlay.innerHTML = `<div class="modal" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-edit"></i> Modifier l'institution</h3><button class="modal-close" id="close-modif-inst-profil"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Nom</label><div class="input-wrapper"><i class="fas fa-school input-icon"></i><input type="text" class="form-input" id="mod-inst-nom-profil" value="${inst.nom||''}"></div></div><div class="input-group"><label class="input-label">Adresse</label><div class="input-wrapper"><i class="fas fa-map-marker-alt input-icon"></i><input type="text" class="form-input" id="mod-inst-adresse-profil" value="${inst.adresse||''}"></div></div><div class="input-group"><label class="input-label">Téléphone</label><div class="input-wrapper"><i class="fas fa-phone input-icon"></i><input type="tel" class="form-input" id="mod-inst-tel-profil" value="${inst.telephone||''}"></div></div><div class="input-group"><label class="input-label">Email</label><div class="input-wrapper"><i class="fas fa-envelope input-icon"></i><input type="email" class="form-input" id="mod-inst-email-profil" value="${inst.email||''}"></div></div><div class="input-group"><label class="input-label">Régime</label><div class="input-wrapper" style="cursor:pointer" id="btn-choisir-regime-profil"><i class="fas fa-calendar-week input-icon"></i><input type="text" class="form-input" id="mod-inst-regime-nom-profil" readonly value="${regimeActuel}" required><input type="hidden" id="mod-inst-regime-profil" value="${inst.regime||'ANGLAIS'}"><i class="fas fa-chevron-down" style="position:absolute;right:0.8rem;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;font-size:0.8rem"></i></div></div><div class="input-group"><label class="input-label">Logo</label><div class="input-wrapper" style="display:flex;align-items:center;gap:0.5rem"><label for="mod-inst-logo-profil" style="display:inline-flex;align-items:center;gap:0.4rem;padding:0.5rem 1rem;background:var(--primary);color:white;border-radius:var(--radius);cursor:pointer;font-size:0.85rem;font-weight:600;transition:var(--transition);white-space:nowrap"><i class="fas fa-upload"></i> Choisir un fichier</label><input type="file" class="form-input" id="mod-inst-logo-profil" accept="image/*" style="display:none"><span id="logo-file-name-profil" style="color:var(--text-muted);font-size:0.8rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:150px">${inst.logo ? 'Logo actuel' : 'Aucun fichier'}</span></div></div></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-modif-inst-profil">Annuler</button><button class="btn btn-primary" id="btn-save-modif-inst-profil"><i class="fas fa-save"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-modif-inst-profil').onclick = () => overlay.remove(); overlay.querySelector('#cancel-modif-inst-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-choisir-regime-profil').onclick = () => this.ouvrirModalRegimeModif(); document.getElementById('mod-inst-logo-profil').addEventListener('change', function() { const fileName = this.files[0]?.name || 'Aucun fichier'; document.getElementById('logo-file-name-profil').textContent = fileName; }); overlay.querySelector('#btn-save-modif-inst-profil').onclick = () => this.modifierInstitution(id); }
    ouvrirModalRegimeModif() { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-regime-modif'; overlay.style.zIndex = '1200'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:420px;max-height:80vh;display:flex;flex-direction:column" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-calendar-week"></i> Choisir le régime</h3><button class="modal-close" id="close-regime-modif"><i class="fas fa-times"></i></button></div><div class="modal-body" style="flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:0.5rem;padding-bottom:0.5rem"><div class="ui-card card-hoverable" id="regime-anglais-modif"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-calendar-check" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Anglais (Lun-Ven)</span></div></div><div class="ui-card card-hoverable" id="regime-francais-modif"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-calendar-alt" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Français (Lun-Sam)</span></div></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-regime-modif').onclick = () => overlay.remove(); overlay.querySelector('#regime-anglais-modif').onclick = () => { document.getElementById('mod-inst-regime-nom-profil').value = 'Anglais (Lun-Ven)'; document.getElementById('mod-inst-regime-profil').value = 'ANGLAIS'; overlay.remove(); }; overlay.querySelector('#regime-francais-modif').onclick = () => { document.getElementById('mod-inst-regime-nom-profil').value = 'Français (Lun-Sam)'; document.getElementById('mod-inst-regime-profil').value = 'FRANCAIS'; overlay.remove(); }; }
    async modifierInstitution(id) { console.log('modifierInstitution appelée, id:', id); const nom = document.getElementById('mod-inst-nom-profil')?.value?.trim(); const adresse = document.getElementById('mod-inst-adresse-profil')?.value?.trim(); const telephone = document.getElementById('mod-inst-tel-profil')?.value?.trim(); const email = document.getElementById('mod-inst-email-profil')?.value?.trim(); const regime = document.getElementById('mod-inst-regime-profil')?.value; const logoFile = document.getElementById('mod-inst-logo-profil')?.files[0]; try { const formData = new FormData(); formData.append('nom', nom || ''); formData.append('adresse', adresse || ''); formData.append('telephone', telephone || ''); formData.append('email', email || ''); formData.append('regime', regime || 'ANGLAIS'); if (logoFile) formData.append('logo', logoFile); const r = await fetch(`${API_URL}/classes/institution/${id}`, { method: 'PUT', headers: { 'Authorization': `Bearer ${getToken()}` }, body: formData }); const data = await r.json(); console.log('Réponse:', data); if (data.success) { document.getElementById('modal-modif-inst-profil')?.remove(); if (regime) setRegime(regime); await updateHeaderInfo(); await this.render(); } else this.ouvrirAlert('Erreur', data.message||'Échec','error'); } catch(e) { console.error('Erreur:', e); this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirModalAjouterNiveau() { const existants = this.institutions.map(i => i.niveau); const disponibles = [{v:'maternelle',l:'Maternelle',i:'child'},{v:'primaire',l:'Primaire',i:'child-reaching'},{v:'secondaire',l:'Secondaire',i:'user-graduate'}].filter(d => !existants.includes(d.v)); if (!disponibles.length) { this.ouvrirAlert('Info', 'Tous les niveaux sont déjà ajoutés.', 'info'); return; } const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-ajout-niveau-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; const itemsHTML = disponibles.map(d => `<div class="ui-card card-hoverable ajout-niv-item-profil" data-niveau="${d.v}"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-${d.i}" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">${d.l}</span></div></div>`).join(''); overlay.innerHTML = `<div class="modal" style="max-width:420px;max-height:80vh;display:flex;flex-direction:column" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-layer-group"></i> Ajouter un niveau</h3><button class="modal-close" id="close-ajout-niveau-profil"><i class="fas fa-times"></i></button></div><div class="modal-body" style="flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:0.5rem;padding-bottom:0.5rem">${itemsHTML}</div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-ajout-niveau-profil').onclick = () => overlay.remove(); overlay.querySelectorAll('.ajout-niv-item-profil').forEach(el => { el.addEventListener('click', () => this.ajouterNiveau(el.dataset.niveau)); }); }
    async ajouterNiveau(niveau) { try { const r = await apiPost('/classes/institution', { nom: this.institutions[0]?.nom || 'Complexe Scolaire Avenir', niveau }); if (r.success) { document.getElementById('modal-ajout-niveau-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    confirmerSuppressionNiveau(id, nom) { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-suppr-niv-profil'; overlay.style.zIndex = '1300'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--danger);margin-bottom:0.75rem;display:block"></i><h3>Supprimer le niveau</h3><p style="color:var(--text-secondary);margin-top:0.5rem">Supprimer <strong>${nom}</strong> et toutes ses classes/élèves ?</p><div style="display:flex;gap:0.5rem;margin-top:1.5rem"><button class="btn btn-ghost btn-full" id="cancel-suppr-niv-profil">Annuler</button><button class="btn btn-danger btn-full" id="btn-suppr-niv-profil"><i class="fas fa-trash"></i> Supprimer</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#cancel-suppr-niv-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-suppr-niv-profil').onclick = () => this.supprimerNiveau(id); }
    async supprimerNiveau(id) { try { const r = await apiDelete(`/classes/institution/${id}`); if (r.success) { document.getElementById('modal-suppr-niv-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirModalAjouterOption() { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-ajout-opt-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:450px" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-cog"></i> Ajouter une option</h3><button class="modal-close" id="close-ajout-opt-profil"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Code <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-code input-icon"></i><input type="text" class="form-input" id="opt-code-profil" placeholder="Ex: CG"></div></div><div class="input-group"><label class="input-label">Nom <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-book input-icon"></i><input type="text" class="form-input" id="opt-nom-profil" placeholder="Ex: Commerciale et Gestion"></div></div></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-ajout-opt-profil">Annuler</button><button class="btn btn-primary" id="btn-save-opt-profil"><i class="fas fa-save"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-ajout-opt-profil').onclick = () => overlay.remove(); overlay.querySelector('#cancel-ajout-opt-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-save-opt-profil').onclick = () => this.ajouterOption(); }
    async ajouterOption() { const code = document.getElementById('opt-code-profil')?.value?.trim(), nom = document.getElementById('opt-nom-profil')?.value?.trim(); if (!code || !nom) { this.ouvrirAlert('Champs requis', 'Remplissez tous les champs.', 'warning'); return; } const instSecondaire = this.institutions.find(i => i.niveau === 'secondaire'); if (!instSecondaire) { this.ouvrirAlert('Erreur', 'Aucune institution secondaire.', 'error'); return; } try { const r = await apiPost('/classes/option/secondaire', { code, nom, institution_id: instSecondaire.id }); if (r.success) { document.getElementById('modal-ajout-opt-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirModalModifierOption(id, code, nom) { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-modif-opt-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:450px" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-edit"></i> Modifier l'option</h3><button class="modal-close" id="close-modif-opt-profil"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Code</label><div class="input-wrapper"><i class="fas fa-code input-icon"></i><input type="text" class="form-input" id="mod-opt-code-profil" value="${code}"></div></div><div class="input-group"><label class="input-label">Nom</label><div class="input-wrapper"><i class="fas fa-book input-icon"></i><input type="text" class="form-input" id="mod-opt-nom-profil" value="${nom}"></div></div></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-modif-opt-profil">Annuler</button><button class="btn btn-primary" id="btn-save-modif-opt-profil"><i class="fas fa-save"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-modif-opt-profil').onclick = () => overlay.remove(); overlay.querySelector('#cancel-modif-opt-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-save-modif-opt-profil').onclick = () => this.modifierOption(id); }
    async modifierOption(id) { const code = document.getElementById('mod-opt-code-profil')?.value?.trim(), nom = document.getElementById('mod-opt-nom-profil')?.value?.trim(); if (!code || !nom) { this.ouvrirAlert('Champs requis', 'Remplissez tous les champs.', 'warning'); return; } try { const r = await apiPut(`/classes/option/${id}`, { code, nom }); if (r.success) { document.getElementById('modal-modif-opt-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    confirmerSuppressionOption(id, nom) { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-suppr-opt-profil'; overlay.style.zIndex = '1300'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--danger);margin-bottom:0.75rem;display:block"></i><h3>Supprimer l'option</h3><p style="color:var(--text-secondary);margin-top:0.5rem">Supprimer <strong>${nom}</strong> et toutes ses classes/élèves ?</p><div style="display:flex;gap:0.5rem;margin-top:1.5rem"><button class="btn btn-ghost btn-full" id="cancel-suppr-opt-profil">Annuler</button><button class="btn btn-danger btn-full" id="btn-suppr-opt-profil"><i class="fas fa-trash"></i> Supprimer</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#cancel-suppr-opt-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-suppr-opt-profil').onclick = () => this.supprimerOption(id); }
    async supprimerOption(id) { try { const r = await apiDelete(`/classes/option/${id}`); if (r.success) { document.getElementById('modal-suppr-opt-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirAlert(titre,message,type){ const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.style.zIndex='2000';overlay.id='alert-'+Date.now();overlay.onclick=e=>{if(e.target===overlay)overlay.remove();};const icones={error:'exclamation-circle',success:'check-circle',warning:'exclamation-triangle',info:'info-circle'};const couleurs={error:'var(--danger)',success:'var(--success)',warning:'var(--warning)',info:'var(--info)'};overlay.innerHTML=`<div class="modal" style="max-width:380px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem 1.5rem"><i class="fas fa-${icones[type]||'info-circle'}" style="font-size:2.5rem;color:${couleurs[type]||'var(--primary)'};margin-bottom:0.75rem;display:block"></i><h3 style="margin-bottom:0.5rem">${titre}</h3><p style="color:var(--text-secondary);font-size:0.9rem">${message}</p><button class="btn btn-primary" style="margin-top:1.25rem;width:100%" id="btn-alert-ok-profil2"><i class="fas fa-check"></i> OK</button></div></div>`;document.body.appendChild(overlay);document.getElementById('btn-alert-ok-profil2').onclick=()=>overlay.remove();}
    async nettoyerIDs() { const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-nettoyer-profil'; overlay.style.zIndex = '1300'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; overlay.innerHTML = `<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem"><i class="fas fa-broom" style="font-size:2.5rem;color:var(--primary);margin-bottom:0.75rem;display:block"></i><h3>Réorganiser les IDs</h3><p style="color:var(--text-secondary);margin-top:0.5rem">Cette action va réorganiser tous les IDs. Continuer ?</p><div style="display:flex;gap:0.5rem;margin-top:1.5rem"><button class="btn btn-ghost btn-full" id="cancel-nettoyer-profil">Annuler</button><button class="btn btn-primary btn-full" id="btn-exec-nettoyer-profil"><i class="fas fa-check"></i> Nettoyer</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#cancel-nettoyer-profil').onclick = () => overlay.remove(); overlay.querySelector('#btn-exec-nettoyer-profil').onclick = () => this.executerNettoyage(); }
    async executerNettoyage() { try { const r = await apiPost('/classes/nettoyer-ids'); if (r.success) { document.getElementById('modal-nettoyer-profil')?.remove(); this.ouvrirAlert('Succès', 'Tous les IDs ont été réorganisés.', 'success'); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
}

class ProfilElevePage {
    constructor(id) { this.id = id; this.eleveData = null; }
    async render() { const m = document.getElementById('main-content'); m.innerHTML = `<div style="text-align:center;padding:3rem"><div class="spinner"></div><p style="color:var(--text-muted);margin-top:0.75rem">Chargement du profil...</p></div>`; try { const res = await API.getEleve(this.id); if (!res.success || !res.data) { m.innerHTML = `<div style="text-align:center;padding:3rem"><i class="fas fa-user-slash" style="font-size:3rem;color:var(--text-muted)"></i><h3 style="margin-top:1rem">Élève non trouvé</h3></div>`; return; } const e = res.data; this.eleveData = e; const photoUrl = e.photo || null; const init = (e.prenom||'').charAt(0)+(e.nom||'').charAt(0); const age = calculerAge(e.date_naissance); const respHTML = (e.responsables||[]).map(r => `<div class="responsable-card" style="display:flex;flex-direction:column;height:100%"><div class="responsable-header"><strong>${r.nom_complet}</strong><span class="badge badge-info">${r.lien_parente}</span></div><div class="responsable-contacts" style="flex:1">${r.telephone?`<a href="tel:${r.telephone}" class="contact-item contact-clickable"><span class="contact-moyen"><i class="fas fa-phone"></i> Téléphone</span><span class="contact-valeur">${r.telephone}</span></a>`:''}${r.whatsapp?`<a href="https://wa.me/${(r.whatsapp||'').replace(/\+/g,'')}" target="_blank" class="contact-item contact-clickable"><span class="contact-moyen"><i class="fab fa-whatsapp"></i> WhatsApp</span><span class="contact-valeur">${r.whatsapp}</span></a>`:''}${r.email?`<a href="mailto:${r.email}" class="contact-item contact-clickable"><span class="contact-moyen"><i class="fas fa-envelope"></i> E-mail</span><span class="contact-valeur">${r.email}</span></a>`:''}</div><button class="btn btn-sm btn-danger no-print suppr-resp-btn" data-id="${r.id}" data-nom="${r.nom_complet.replace(/"/g,'&quot;')}" style="margin-top:auto;width:100%"><i class="fas fa-trash"></i> Supprimer</button></div>`).join(''); const taux = e.taux_presence||0; const tauxColor = taux>=70?'var(--success)':taux>=50?'var(--warning)':'var(--danger)'; m.innerHTML = `<div class="profil-eleve-container"><div class="print-header" style="display:none;text-align:center;border-bottom:2px solid #000;padding-bottom:15px;margin-bottom:15px"><div style="display:flex;align-items:center;justify-content:center;gap:15px"><img src="/assets/logo-ecole.png" alt="Logo" style="width:60px;height:60px;border-radius:10px;object-fit:cover"><div style="text-align:left"><h2 style="margin:0;font-size:1.2rem;font-weight:800" id="print-inst-nom">EduManage</h2><p style="margin:2px 0;font-size:0.85rem" id="print-inst-adr">Adresse non renseignée</p><p style="margin:2px 0;font-size:0.85rem" id="print-inst-contact">Contact non renseigné</p></div></div></div><div class="no-print" style="display:flex;align-items:center;gap:0.5rem;margin-bottom:1.5rem;margin-top:7rem"><button class="btn btn-ghost" id="btn-retour-profil"><i class="fas fa-arrow-left"></i> Retour</button><button class="btn btn-sm btn-warning" id="btn-modifier-profil" style="margin-left:auto"><i class="fas fa-edit"></i> Modifier</button></div><div class="profil-header-card"><div class="profil-photo-wrapper no-print" id="photo-wrapper" style="cursor:pointer">${photoUrl?`<img src="${photoUrl}" alt="Photo" class="profil-photo-img"><div class="photo-overlay"><i class="fas fa-search-plus"></i></div>`:`<div class="profil-avatar-lg" style="background:var(--gradient-${e.genre==='F'?'3':'1'})">${init}</div>`}</div><div style="flex:1"><h2>${e.prenom} ${e.nom}</h2><div style="display:flex;gap:1rem;color:var(--text-secondary);margin-top:0.5rem;flex-wrap:wrap"><span><i class="fas fa-id-card"></i> ${e.matricule}</span><span><i class="fas fa-graduation-cap"></i> ${e.classe_nom||'N/A'}</span><span><i class="fas fa-calendar"></i> ${formatDateShort(e.date_inscription)}</span><span><i class="fas fa-birthday-cake"></i> ${age} ans</span></div></div></div><div class="profil-grid-top"><div class="profil-section"><h3><i class="fas fa-address-card"></i> Identité</h3><div class="info-liste"><div class="info-item"><span class="info-label">Date de naissance</span><span class="info-value">${formatDate(e.date_naissance)}</span></div><div class="info-item"><span class="info-label">Genre</span><span class="info-value"><span class="badge badge-info"><i class="fas fa-${e.genre==='M'?'mars':'venus'}"></i> ${e.genre==='M'?'Masculin':'Féminin'}</span></span></div><div class="info-item"><span class="info-label">Adresse</span><span class="info-value">${e.adresse||'Non renseignée'}</span></div><div class="info-item"><span class="info-label">Âge</span><span class="info-value">${age} ans</span></div></div></div><div class="profil-section no-print"><h3><i class="fas fa-qrcode"></i> Carte d'identité</h3><div style="text-align:center;padding:1rem">${e.qr_code?`<img src="${e.qr_code}" alt="QR Code" style="width:160px;height:160px;border-radius:var(--radius);background:white;padding:0.5rem"><div class="no-print" style="margin-top:0.75rem"><button class="btn btn-sm btn-primary" id="btn-download-qr"><i class="fas fa-download"></i> Télécharger</button></div>`:'<p style="color:var(--text-muted)">Aucun QR code généré</p>'}</div></div></div><div class="profil-section" style="margin-top:1rem"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem"><h3 style="margin:0"><i class="fas fa-users"></i> Responsables</h3><button class="btn btn-sm btn-primary no-print" id="btn-ajout-resp-profil"><i class="fas fa-plus"></i> Ajouter</button></div><div class="responsables-grid">${respHTML||'<p style="color:var(--text-muted);text-align:center;padding:1rem;grid-column:1/-1">Aucun responsable enregistré</p>'}</div></div><div class="profil-section no-print" style="margin-top:1rem"><h3><i class="fas fa-fingerprint"></i> Empreinte digitale</h3><div style="text-align:center;padding:1rem">${e.empreinte_digitale?`<i class="fas fa-check-circle" style="font-size:3rem;color:var(--success);display:block;margin-bottom:0.5rem"></i><p style="color:var(--success);font-weight:600">Empreinte enregistrée</p><p style="color:var(--text-muted);font-size:0.8rem">ID: ${e.empreinte_digitale}</p><button class="btn btn-sm btn-danger" id="btn-suppr-emp"><i class="fas fa-trash"></i> Supprimer</button>`:`<i class="fas fa-fingerprint" style="font-size:3rem;color:var(--text-muted);display:block;margin-bottom:0.5rem"></i><p style="color:var(--text-muted)">Aucune empreinte</p><button class="btn btn-sm btn-primary" id="btn-scan-emp"><i class="fas fa-fingerprint"></i> Scanner</button>`}</div></div><div class="profil-section" style="margin-top:1rem"><h3><i class="fas fa-chart-bar"></i> Fréquentation</h3><div style="text-align:center;padding:1rem 0"><div style="width:140px;height:140px;border-radius:50%;background:conic-gradient(${tauxColor} ${taux}%,var(--input-bg) ${taux}%);display:flex;align-items:center;justify-content:center;margin:0 auto"><div style="width:105px;height:105px;border-radius:50%;background:var(--glass);display:flex;flex-direction:column;align-items:center;justify-content:center"><span style="font-size:2rem;font-weight:800;color:${tauxColor}">${taux}%</span><span style="font-size:0.7rem;color:var(--text-muted)">présence</span></div></div></div><div style="display:flex;gap:1rem;justify-content:center;margin-top:0.5rem"><span style="text-align:center"><i class="fas fa-check-circle" style="color:var(--success);font-size:1.2rem"></i><div style="font-weight:700">${e.stats_presence?.presents||0}</div><div style="font-size:0.7rem;color:var(--text-muted)">présences</div></span><span style="text-align:center"><i class="fas fa-times-circle" style="color:var(--danger);font-size:1.2rem"></i><div style="font-weight:700">${e.stats_presence?.absents||0}</div><div style="font-size:0.7rem;color:var(--text-muted)">absences</div></span><span style="text-align:center"><i class="fas fa-clock" style="color:var(--warning);font-size:1.2rem"></i><div style="font-weight:700">${e.stats_presence?.retards||0}</div><div style="font-size:0.7rem;color:var(--text-muted)">retards</div></span></div>${this.genererCalendrier(e.presences||[])}<div class="no-print" style="text-align:center;margin-top:1.5rem"><button class="btn btn-sm btn-outline" id="btn-imprimer"><i class="fas fa-print"></i> Imprimer la fiche</button></div></div></div>`; window.profilEleve = this; this.bindEvents(); const instRes = await apiGet('/classes/institutions'); const inst = (instRes.data||[])[0] || {}; setTimeout(() => { const n=document.getElementById('print-inst-nom'),a=document.getElementById('print-inst-adr'),c=document.getElementById('print-inst-contact'); if(n)n.textContent=inst.nom||'EduManage'; if(a)a.innerHTML=`<i class="fas fa-map-marker-alt"></i> ${inst.adresse||'Adresse non renseignée'}`; if(c)c.innerHTML=`<i class="fas fa-phone"></i> ${inst.telephone||'Non renseigné'} | <i class="fas fa-envelope"></i> ${inst.email||'Non renseigné'}`; },100); } catch(e) { m.innerHTML = `<div style="text-align:center;padding:3rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--text-muted)"></i><p>${e.message}</p></div>`; } }
    bindEvents() { document.getElementById('btn-retour-profil')?.addEventListener('click', () => router.navigate('classe/' + (this.eleveData?.classe_id || this.id))); document.getElementById('btn-modifier-profil')?.addEventListener('click', () => this.ouvrirModalModifier()); document.getElementById('photo-wrapper')?.addEventListener('click', () => this.ouvrirApercuPhoto()); document.getElementById('btn-download-qr')?.addEventListener('click', () => this.telechargerQR()); document.getElementById('btn-ajout-resp-profil')?.addEventListener('click', () => this.ouvrirModalAjouterResponsable(this.id)); document.getElementById('btn-imprimer')?.addEventListener('click', () => this.imprimerFiche()); document.getElementById('btn-suppr-emp')?.addEventListener('click', () => this.confirmerSuppressionEmpreinte(this.id)); document.getElementById('btn-scan-emp')?.addEventListener('click', () => this.enregistrerEmpreinte(this.id)); document.querySelectorAll('.suppr-resp-btn').forEach(btn => { btn.addEventListener('click', (ev) => { ev.stopPropagation(); this.confirmerSuppressionResponsable(parseInt(btn.dataset.id), btn.dataset.nom); }); }); }
    ouvrirApercuPhoto() { const e=this.eleveData; const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-photo';overlay.style.zIndex='1500'; overlay.onclick=ev=>{if(ev.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-camera"></i> Photo de profil</h3><button class="modal-close" id="close-photo"><i class="fas fa-times"></i></button></div><div class="modal-body" style="padding:1.5rem">${e.photo?`<img src="${e.photo}" alt="Photo" style="width:100%;max-height:350px;object-fit:contain;border-radius:var(--radius)">`:`<div style="width:120px;height:120px;border-radius:50%;background:var(--gradient-1);display:flex;align-items:center;justify-content:center;color:white;font-size:3rem;margin:0 auto">${(e.prenom||'').charAt(0)+(e.nom||'').charAt(0)}</div>`}<div style="margin-top:1rem"><input type="file" id="photo-input" accept="image/*" style="display:none"><button class="btn btn-sm btn-primary" id="btn-changer-photo"><i class="fas fa-edit"></i> Modifier la photo</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-photo').onclick=()=>overlay.remove(); overlay.querySelector('#btn-changer-photo').onclick=()=>document.getElementById('photo-input').click(); document.getElementById('photo-input').onchange=()=>this.changerPhoto(); }
    async changerPhoto() { const file=document.getElementById('photo-input')?.files[0];if(!file)return; const fd=new FormData();fd.append('photo',file);fd.append('nom',this.eleveData.nom||'');fd.append('prenom',this.eleveData.prenom||'');fd.append('date_naissance',(this.eleveData.date_naissance||'').split('T')[0]);fd.append('genre',this.eleveData.genre||'');fd.append('adresse',this.eleveData.adresse||''); try{const r=await fetch(`${API_URL}/eleves/${this.id}`,{method:'PUT',headers:{'Authorization':`Bearer ${getToken()}`},body:fd});const d=await r.json();if(d.success){document.getElementById('modal-photo')?.remove();await this.render();}else this.ouvrirAlert('Erreur',d.message||'Échec','error');} catch(ex){this.ouvrirAlert('Erreur',ex.message,'error');} }
    telechargerQR(){const e=this.eleveData;if(e.qr_code){const a=document.createElement('a');a.href=e.qr_code;a.download=`QR_${e.matricule}.png`;a.click();}}
    imprimerFiche() { const e=this.eleveData; const nomFichier = `Fiche_${(e.prenom||'').replace(/\s+/g,'_')}_${(e.nom||'').replace(/\s+/g,'_')}`; const oldTitle=document.title;document.title=nomFichier;window.print();setTimeout(()=>{document.title=oldTitle;},100); }
    genererCalendrier(presences) { const now=new Date(),mois=now.getMonth(),annee=now.getFullYear(); const moisNoms=['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre']; const joursDansMois=new Date(annee,mois+1,0).getDate(),premierJour=new Date(annee,mois,1).getDay()||7; const presencesMap={};presences.forEach(p=>{presencesMap[p.date_presence.split('T')[0]]=p.statut;}); const statsParJour={present:'Présent',absent:'Absent',retard:'Retard',justifie:'Justifié'}; let html=`<div style="margin-top:1.5rem"><h4 style="font-size:0.85rem;color:var(--text-secondary);margin-bottom:0.75rem;text-align:center">${moisNoms[mois]} ${annee}</h4><div class="calendrier-grid"><div class="calendrier-day-name">Lun</div><div class="calendrier-day-name">Mar</div><div class="calendrier-day-name">Mer</div><div class="calendrier-day-name">Jeu</div><div class="calendrier-day-name">Ven</div><div class="calendrier-day-name">Sam</div><div class="calendrier-day-name">Dim</div>`; for(let i=1;i<premierJour;i++)html+=`<div class="calendrier-day empty"></div>`; for(let j=1;j<=joursDansMois;j++){const dateStr=`${annee}-${String(mois+1).padStart(2,'0')}-${String(j).padStart(2,'0')}`;const statut=presencesMap[dateStr]||'';const sc=statut==='present'?'present':statut==='absent'?'absent':statut==='retard'?'retard':statut==='justifie'?'justifie':'';const tooltip=statut?`${j} ${moisNoms[mois]} : ${statsParJour[statut]||statut}`:`${j} ${moisNoms[mois]}`;const today=new Date().toDateString()===new Date(dateStr).toDateString()?'today':'';html+=`<div class="calendrier-day ${sc} ${today}" title="${tooltip}">${j}</div>`;} html+=`</div><div style="display:flex;gap:1rem;justify-content:center;margin-top:0.75rem;font-size:0.7rem"><span><span class="calendrier-dot present"></span> Présent</span><span><span class="calendrier-dot absent"></span> Absent</span><span><span class="calendrier-dot retard"></span> Retard</span><span><span class="calendrier-dot justifie"></span> Justifié</span></div></div>`; return html; }
    ouvrirModalModifier() { const e=this.eleveData;if(!e)return; const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-modifier'; overlay.onclick=ev=>{if(ev.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-edit"></i> Modifier l'élève</h3><button class="modal-close" id="close-modifier"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Nom <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-user input-icon"></i><input type="text" class="form-input" id="mod-nom" value="${e.nom||''}" required></div></div><div class="input-group"><label class="input-label">Prénom <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-user input-icon"></i><input type="text" class="form-input" id="mod-prenom" value="${e.prenom||''}" required></div></div><div class="input-group"><label class="input-label">Date de naissance <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-calendar input-icon"></i><input type="date" class="form-input" id="mod-date" value="${(e.date_naissance||'').split('T')[0]}" required></div></div><div class="input-group"><label class="input-label">Genre <span class="required">*</span></label><div class="input-wrapper" style="cursor:pointer" id="btn-genre-modif"><i class="fas fa-venus-mars input-icon"></i><input type="text" class="form-input" id="mod-genre-nom" readonly value="${e.genre==='M'?'Masculin':'Féminin'}" required><input type="hidden" id="mod-genre" value="${e.genre||''}"><i class="fas fa-chevron-down" style="position:absolute;right:0.8rem;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;font-size:0.8rem"></i></div></div><div class="input-group"><label class="input-label">Adresse</label><div class="input-wrapper"><i class="fas fa-map-marker-alt input-icon"></i><input type="text" class="form-input" id="mod-adresse" value="${e.adresse||''}"></div></div><p style="color:var(--text-muted);font-size:0.8rem;margin-top:0.5rem"><i class="fas fa-info-circle"></i> Matricule et classe non modifiables.</p></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-modifier">Annuler</button><button class="btn btn-primary" id="btn-save-modifier"><i class="fas fa-save"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-modifier').onclick=()=>overlay.remove(); overlay.querySelector('#cancel-modifier').onclick=()=>overlay.remove(); overlay.querySelector('#btn-genre-modif').onclick=()=>this.ouvrirModalGenreModif(); overlay.querySelector('#btn-save-modifier').onclick=()=>this.enregistrerModifications(); }
    ouvrirModalGenreModif() { const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-genre-modif';overlay.style.zIndex='1200'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; const itemsHTML=`<div class="ui-card card-hoverable" id="genre-m-modif"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-mars" style="color:#3b82f6;font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Masculin</span></div></div><div class="ui-card card-hoverable" id="genre-f-modif"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-venus" style="color:#ec4899;font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">Féminin</span></div></div>`; overlay.innerHTML=await CL.render('ui/list-modal',{id:'modal-genre-modif',icon:'venus-mars',title:'Choisir le genre',items:itemsHTML}); document.body.appendChild(overlay); const gM=overlay.querySelector('#genre-m-modif'), gF=overlay.querySelector('#genre-f-modif'); if(gM)gM.onclick=()=>{document.getElementById('mod-genre-nom').value='Masculin';document.getElementById('mod-genre').value='M';overlay.remove();}; if(gF)gF.onclick=()=>{document.getElementById('mod-genre-nom').value='Féminin';document.getElementById('mod-genre').value='F';overlay.remove();}; }
    async enregistrerModifications() { const nom=document.getElementById('mod-nom')?.value?.trim(),prenom=document.getElementById('mod-prenom')?.value?.trim(),date_naissance=document.getElementById('mod-date')?.value,genre=document.getElementById('mod-genre')?.value,adresse=document.getElementById('mod-adresse')?.value?.trim(); if(!nom||!prenom||!date_naissance||!genre){this.ouvrirAlert('Champs requis','Veuillez remplir tous les champs obligatoires.','warning');return;} try{const r=await apiPut(`/eleves/${this.id}`,{nom,prenom,date_naissance,genre,adresse});if(r.success){document.getElementById('modal-modifier')?.remove();await this.render();}else this.ouvrirAlert('Erreur',r.message||'Échec','error');} catch(e){this.ouvrirAlert('Erreur',e.message,'error');} }
    ouvrirModalAjouterResponsable(eleveId) { if((this.eleveData?.responsables||[]).length>=3){this.ouvrirAlert('Limite','Maximum 3 responsables.','warning');return;} const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-ajout-resp'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-user-plus"></i> Ajouter un responsable</h3><button class="modal-close" id="close-ajout-resp"><i class="fas fa-times"></i></button></div><div class="modal-body"><form onsubmit="return false"><div class="input-group"><label class="input-label">Nom complet <span class="required">*</span></label><div class="input-wrapper"><i class="fas fa-user input-icon"></i><input type="text" class="form-input" id="resp-nom" required></div></div><div class="input-group"><label class="input-label">Lien <span class="required">*</span></label><div class="input-wrapper" style="cursor:pointer" id="btn-lien-resp"><i class="fas fa-link input-icon"></i><input type="text" class="form-input" id="resp-lien-nom" readonly placeholder="Cliquer..." required><input type="hidden" id="resp-lien" value=""><i class="fas fa-chevron-down" style="position:absolute;right:0.8rem;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;font-size:0.8rem"></i></div></div><div class="input-group"><label class="input-label">Téléphone</label><div class="input-wrapper"><i class="fas fa-phone input-icon"></i><input type="tel" class="form-input" id="resp-tel"></div></div><div class="input-group"><label class="input-label">WhatsApp</label><div class="input-wrapper"><i class="fab fa-whatsapp input-icon"></i><input type="tel" class="form-input" id="resp-whatsapp"></div></div><div class="input-group"><label class="input-label">Email</label><div class="input-wrapper"><i class="fas fa-envelope input-icon"></i><input type="email" class="form-input" id="resp-email"></div></div></form></div><div class="modal-footer"><button class="btn btn-ghost" id="cancel-ajout-resp">Annuler</button><button class="btn btn-primary" id="btn-save-resp"><i class="fas fa-save"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-ajout-resp').onclick=()=>overlay.remove(); overlay.querySelector('#cancel-ajout-resp').onclick=()=>overlay.remove(); overlay.querySelector('#btn-lien-resp').onclick=()=>this.ouvrirModalLien(); overlay.querySelector('#btn-save-resp').onclick=()=>this.ajouterResponsable(eleveId); }
    async ouvrirModalLien() { const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-lien';overlay.style.zIndex='1200'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; const liens=['Père','Mère','Tuteur','Tutrice','Frère','Sœur','Oncle','Tante','Grand-père','Grand-mère','Proche']; const icones={'Père':'male','Mère':'female','Tuteur':'user-tie','Tutrice':'user-tie','Frère':'user','Sœur':'user','Oncle':'user','Tante':'user','Grand-père':'user','Grand-mère':'user','Proche':'user-friends'}; const itemsHTML=liens.map(l=>`<div class="ui-card card-hoverable lien-item" data-lien="${l}"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-${icones[l]||'user'}" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">${l}</span></div></div>`).join(''); overlay.innerHTML=await CL.render('ui/list-modal',{id:'modal-lien',icon:'link',title:'Lien de parenté',items:itemsHTML}); document.body.appendChild(overlay); overlay.querySelectorAll('.lien-item').forEach(el=>{el.onclick=()=>{document.getElementById('resp-lien-nom').value=el.dataset.lien;document.getElementById('resp-lien').value=el.dataset.lien.toLowerCase();overlay.remove();};}); }
    async ajouterResponsable(eleveId) { const nom_complet=document.getElementById('resp-nom')?.value?.trim(),lien_parente=document.getElementById('resp-lien')?.value; if(!nom_complet||!lien_parente){this.ouvrirAlert('Champs requis','Nom et lien obligatoires.','warning');return;} try{const r=await apiPost('/eleves/responsable',{eleve_id:eleveId,nom_complet,lien_parente,telephone:document.getElementById('resp-tel')?.value?.trim()||null,whatsapp:document.getElementById('resp-whatsapp')?.value?.trim()||null,email:document.getElementById('resp-email')?.value?.trim()||null});if(r.success){document.getElementById('modal-ajout-resp')?.remove();await this.render();}else this.ouvrirAlert('Erreur',r.message||'Échec','error');} catch(e){this.ouvrirAlert('Erreur',e.message,'error');} }
    confirmerSuppressionResponsable(responsableId,nom) { const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-suppr-resp';overlay.style.zIndex='1300'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--danger);margin-bottom:0.75rem;display:block"></i><h3>Supprimer le responsable</h3><p style="color:var(--text-secondary);margin-top:0.5rem">Supprimer <strong>${nom}</strong> ?</p><div style="display:flex;gap:0.5rem;margin-top:1.5rem"><button class="btn btn-ghost btn-full" id="cancel-suppr-resp">Annuler</button><button class="btn btn-danger btn-full" id="btn-suppr-resp"><i class="fas fa-trash"></i> Supprimer</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#cancel-suppr-resp').onclick=()=>overlay.remove(); overlay.querySelector('#btn-suppr-resp').onclick=()=>this.supprimerResponsable(responsableId); }
    async supprimerResponsable(responsableId){try{const r=await apiDelete(`/eleves/responsable/${responsableId}`);if(r.success){document.getElementById('modal-suppr-resp')?.remove();await this.render();}else this.ouvrirAlert('Erreur',r.message||'Échec','error');}catch(e){this.ouvrirAlert('Erreur',e.message,'error');}}
    async enregistrerEmpreinte(eleveId) { try { if (window.PublicKeyCredential && navigator.credentials) { const challenge = new Uint8Array(32); crypto.getRandomValues(challenge); const credential = await navigator.credentials.create({ publicKey: { challenge, rp: { name: 'EduManage', id: window.location.hostname }, user: { id: new Uint8Array(16), name: `eleve-${eleveId}`, displayName: `Élève ${eleveId}` }, pubKeyCredParams: [{ type: 'public-key', alg: -7 }], timeout: 60000, authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required' }, attestation: 'none' } }); const empreinteId = btoa(String.fromCharCode(...new Uint8Array(credential.rawId))); const r = await apiPost(`/eleves/${eleveId}/empreinte`, { empreinte_digitale: empreinteId }); if (r.success) { await this.render(); this.ouvrirAlert('Succès', 'Empreinte enregistrée avec succès !', 'success'); } else this.ouvrirAlert('Erreur', r.message || 'Échec', 'error'); return; } } catch(e) { if (e.name === 'NotAllowedError') { this.ouvrirAlert('Annulé', 'Enregistrement annulé par l\'utilisateur.', 'info'); return; } } this.ouvrirModalSaisieEmpreinte(eleveId); }
    ouvrirModalSaisieEmpreinte(eleveId) { const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-empreinte'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-fingerprint"></i> Enregistrer l'empreinte</h3><button class="modal-close" id="close-emp"><i class="fas fa-times"></i></button></div><div class="modal-body" style="padding:2rem"><i class="fas fa-fingerprint" style="font-size:4rem;color:var(--primary);display:block;margin-bottom:1rem;animation:pulse 1.5s infinite"></i><p style="margin-bottom:1rem">Lecteur biométrique non détecté. Saisissez un ID :</p><div class="input-group"><div class="input-wrapper"><i class="fas fa-id-card input-icon"></i><input type="text" class="form-input" id="empreinte-id" placeholder="Ex: EMP-001"></div></div><button class="btn btn-primary btn-full" id="btn-save-emp" style="margin-top:1rem"><i class="fas fa-check"></i> Enregistrer</button></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-emp').onclick=()=>overlay.remove(); overlay.querySelector('#btn-save-emp').onclick=()=>this.simulerEmpreinte(eleveId); }
    async simulerEmpreinte(eleveId){const empreinteId=document.getElementById('empreinte-id')?.value?.trim()||('EMP-'+Date.now());try{const r=await apiPost(`/eleves/${eleveId}/empreinte`,{empreinte_digitale:empreinteId});if(r.success){document.getElementById('modal-empreinte')?.remove();await this.render();this.ouvrirAlert('Succès','Empreinte enregistrée !','success');}else this.ouvrirAlert('Erreur',r.message||'Échec','error');}catch(e){this.ouvrirAlert('Erreur',e.message,'error');}}
    confirmerSuppressionEmpreinte(eleveId) { const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.id='modal-suppr-emp';overlay.style.zIndex='1300'; overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; overlay.innerHTML=`<div class="modal" style="max-width:400px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem"><i class="fas fa-exclamation-triangle" style="font-size:2.5rem;color:var(--danger);margin-bottom:0.75rem;display:block"></i><h3>Supprimer l'empreinte</h3><p style="color:var(--text-secondary);margin-top:0.5rem">Voulez-vous vraiment supprimer cette empreinte ?</p><div style="display:flex;gap:0.5rem;margin-top:1.5rem"><button class="btn btn-ghost btn-full" id="cancel-suppr-emp">Annuler</button><button class="btn btn-danger btn-full" id="btn-del-emp"><i class="fas fa-trash"></i> Supprimer</button></div></div></div>`; document.body.appendChild(overlay); overlay.querySelector('#cancel-suppr-emp').onclick=()=>overlay.remove(); overlay.querySelector('#btn-del-emp').onclick=()=>this.supprimerEmpreinte(eleveId); }
    async supprimerEmpreinte(eleveId){try{const r=await apiDelete(`/eleves/${eleveId}/empreinte`);if(r.success){document.getElementById('modal-suppr-emp')?.remove();await this.render();}else this.ouvrirAlert('Erreur',r.message||'Échec','error');}catch(e){this.ouvrirAlert('Erreur',e.message,'error');}}
    ouvrirAlert(titre,message,type){ const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.style.zIndex='2000';overlay.id='alert-'+Date.now(); overlay.onclick=e=>{if(e.target===overlay)overlay.remove();}; const icones={error:'exclamation-circle',success:'check-circle',warning:'exclamation-triangle',info:'info-circle'}; const couleurs={error:'var(--danger)',success:'var(--success)',warning:'var(--warning)',info:'var(--info)'}; overlay.innerHTML=`<div class="modal" style="max-width:380px;text-align:center" onclick="event.stopPropagation()"><div class="modal-body" style="padding:2rem 1.5rem"><i class="fas fa-${icones[type]||'info-circle'}" style="font-size:2.5rem;color:${couleurs[type]||'var(--primary)'};margin-bottom:0.75rem;display:block"></i><h3 style="margin-bottom:0.5rem">${titre}</h3><p style="color:var(--text-secondary);font-size:0.9rem">${message}</p><button class="btn btn-primary" style="margin-top:1.25rem;width:100%" id="btn-alert-ok"><i class="fas fa-check"></i> OK</button></div></div>`; document.body.appendChild(overlay); document.getElementById('btn-alert-ok').onclick=()=>overlay.remove(); }
}

async function initApp() {
    if (!authService.isAuth()) { window.location.href = '/login.html'; return; }
    const user = authService.getUser();
    if (localStorage.getItem('theme') === 'light') document.body.classList.add('light');
    const roleLabels = { super_admin: 'Super Admin', admin: 'Admin', secretaire: 'Secrétaire' };
    document.getElementById('header-container').innerHTML = `<header class="main-header"><div class="header-left"><img src="/assets/logo-ecole.png" alt="Logo" class="header-logo" id="header-logo" onerror="this.style.display='none'"><div class="header-info"><h1 id="header-institution-nom">EduManage</h1><span class="badge badge-info header-badge" id="header-institution-niveau"></span></div><span class="badge badge-info" id="header-role" style="font-size:0.78rem;padding:0.35rem 0.8rem;margin:0 1rem;flex-shrink:0">${roleLabels[user?.role] || user?.role || 'Admin'}</span></div><div class="header-right"><button class="theme-toggle" id="theme-toggle" onclick="toggleTheme()"><i class="fas fa-moon"></i></button><button class="theme-toggle" onclick="router.navigate('profil')" title="Paramètres"><i class="fas fa-cog"></i></button><button class="btn-logout" onclick="authService.logout()"><i class="fas fa-sign-out-alt"></i> <span class="hide-mobile">Quitter</span></button></div></header>`;
    updateThemeIcon(); updateHeaderInfo();
    const components = ['button','input','select','modal','card','table','badge','alert','loader','textarea'];
    for (const c of components) { try { CL.register(`ui/${c}`, await CL.loadTemplate(`/composants/ui/${c}.html`)); } catch(e) {} }
    try { CL.register('forms/search-bar', await CL.loadTemplate('/composants/forms/search-bar.html')); } catch(e) {}
    try { CL.register('ui/list-modal', await CL.loadTemplate('/composants/ui/list-modal.html')); } catch(e) {}
    dashboard = new DashboardPage(); router.add('dashboard', () => dashboard.render());
    router.add('classe/:id', (p) => { classeDetail = new ClasseDetailPage(p.id); classeDetail.render(p); });
    router.add('eleves/:id', (p) => new ProfilElevePage(p.id).render());
    router.add('profil', () => { profilInstitution = new ProfilInstitutionPage(); profilInstitution.render(); });
    router.add('pointage', () => { pointagePage = new PointagePage(); pointagePage.render(); });
    router.navigate(window.location.hash.slice(1) || 'dashboard');
    pointageService.start();
}

async function updateHeaderInfo(institutionActive) { try { const res = await fetch('/api/classes/institutions').then(r => r.json()); const institutions = res.data || []; const inst = institutionActive || (institutions.length ? institutions[0] : null); if (!inst) return; const nomEl = document.getElementById('header-institution-nom'); const nivEl = document.getElementById('header-institution-niveau'); const logoEl = document.getElementById('header-logo'); if (nomEl) nomEl.textContent = inst.nom || 'EduManage'; if (nivEl) nivEl.innerHTML = `<i class="fas fa-school"></i> ${inst.niveau || ''}`; if (logoEl) { logoEl.src = inst.logo || '/assets/logo-ecole.png'; logoEl.onerror = () => { logoEl.style.display = 'none'; }; } if (inst.regime) { setRegime(inst.regime); } } catch(e) {} }
function toggleTheme() { const btn = document.getElementById('theme-toggle'); if (!btn) return; btn.classList.add('switching'); setTimeout(() => { document.body.classList.toggle('light'); localStorage.setItem('theme', document.body.classList.contains('light') ? 'light' : 'dark'); updateThemeIcon(); btn.classList.remove('switching'); }, 300); }
function updateThemeIcon() { const i = document.querySelector('#theme-toggle i'); if (i) i.className = document.body.classList.contains('light') ? 'fas fa-sun' : 'fas fa-moon'; }
function closeModal(id) { const m = document.getElementById(`${id}-overlay`); if (m) m.remove(); }
function confirmModal(id) { closeModal(id); }
document.addEventListener('DOMContentLoaded', initApp);